"""Transcribe inspected cocoa food rows from agency and multi-food tables."""
from pathlib import Path
import json, hashlib
ROOT=Path(__file__).resolve().parents[4];D=ROOT/'data/evidence/contracts/cocoa'
rs=json.loads((D/'review-index.json').read_text())['records']
def source(prefix):return next(r for r in rs if r['source_id'].startswith(prefix))
def save(r,rows,**extra):
    assert hashlib.sha256(Path(r['resolved_path']).read_bytes()).hexdigest()==r['artifact_sha256']
    obj=dict(source_id=r['source_id'],artifact=r['resolved_path'],sha256=r['artifact_sha256'],identity_verified=True,completeness_verified=True,rows=rows,**extra)
    (D/'extractions'/(r['source_id']+'.json')).write_text(json.dumps(obj,ensure_ascii=False,indent=2)+'\n')
r=source('cfs2013');rows=[]
for metal,mean,lo,hi,unit,page in [('Al',11,4,19,'mg/kg',77),('Sb',6,3,14,'µg/kg',81),('Cd',78,16,120,'µg/kg',85),('Pb',17,7,29,'µg/kg',89),('Ni',1400,510,1800,'µg/kg',95),('Sn',.005,None,None,'mg/kg',99),('V',40,15,71,'µg/kg',103)]:
    factor=1 if unit=='mg/kg' else .001;tin=metal=='Sn'
    rows.append(dict(id=f'cfs2013-chocolate-{metal}',analyte=metal,form='chocolate, source total-diet food item',
        market='Hong Kong purchase market; growing origins not reported',year='March 2010–February 2011',n=4,
        sample_unit='measured total-diet composite of three purchases per occasion',
        n_note='Four collection occasions; 12 purchased samples combined into four measured composites, not 12 independent concentration observations.',
        reported=dict(mean=mean,min=lo,max=hi,unit=unit,range_text='ND' if tin else f'{lo}–{hi}'),
        statistic='reported arithmetic mean and composite min–max' if not tin else 'all four composite results below LOD; printed mean uses half-LOD substitution',
        value=None if tin else mean*factor,lower_bound=0 if tin else mean*factor,upper_bound=.01 if tin else mean*factor,
        unit='mg/kg',basis='prepared as normally consumed, homogenized food composite; no dry-weight correction',
        locator=f'Appendix food-level concentration table, PDF page {page}, Chocolate; Methods PDF pages 10–12',
        censoring='All Sn results <10 µg/kg (.01 mg/kg). Printed .005 mg/kg is half-LOD substitution, not observed concentration.' if tin else 'All chocolate results above LOD; source mean/range retained, no inference from category-level non-detect percentage.',
        method='Closed-vessel nitric-acid microwave digestion, high-resolution ICP-MS; Methods page 11.',
        analytical_limits_original_ug_kg={'Al':[100,500],'Sb':[1,5],'Cd':[2,10],'Pb':[2,10],'Ni':[20,100],'Sn':[10,50],'V':[3,15]}[metal],
        limitations='Food-item summary, not an authenticated cocoa-growing origin or a pure cocoa-powder measurement. Rounded values below LOQ remain as printed source estimates.'))
save(r,rows,extraction_complete=True,identity_proof='Complete 111-page First Hong Kong Total Diet Study, Metallic Contaminants, January 2013, official Centre for Food Safety report; Methods, seven food-level appendices and exposure appendices verified.',complete_scope='All seven chocolate concentration rows: Al, Sb, Cd, Pb, Ni, Sn, V. Methylmercury was tested only in 51 mostly animal/seafood food items; no chocolate result exists in that species table. No chocolate mercury zero invented.')
print('CFS:',len(rows),'all chocolate metal rows; Sn retained as a bound.')

r=source('stahl2017');rows=[]
for material,n,lo,hi,mean,median in [('cocoa powder',37,80,312,165,160),('chocolate',84,6,150,48,39)]:
    rows.append(dict(id='stahl2017-Al-'+material.replace(' ','-'),analyte='Al',form=material,market='German official food monitoring laboratory data; growing origin unspecified',year='Results obtained since 2011; end of sampling not specified in table',n=n,sample_unit='tested food sample',reported=dict(min=lo,max=hi,mean=mean,median=median,unit='mg/kg'),value=median,lower_bound=median,upper_bound=median,unit='mg/kg',statistic='source minimum, maximum, arithmetic mean and median',basis='foodstuff as tested; no moisture normalization reported in summary',locator='Table 3, PDF page 3; preceding monitoring-data paragraph PDF page 2',censoring='Both cocoa/chocolate minima quantified; no non-detect substitution needed for these groups.',limitations='Table modified from Stahl reference 16 and reports Hessian official monitoring data. Potential overlap with Fechner German monitoring must be reconciled before independent-family pooling; publication dates are not independent sample identities.'))
save(r,rows,extraction_complete=True,identity_proof='Stahl et al., Environmental Sciences Europe (2017) 29:19, complete eight-page Part I article; Table 3 food monitoring results and footnotes checked.',complete_scope='Both specifically cocoa/chocolate monitoring groups in Table 3. General confectionery category is not an isolated cocoa material; broad EFSA literature concentration bands in Table 2 are secondary, not additional independent samples.',reference_overlap_review='Hessian monitoring since 2011 may overlap Fechner German Food Monitoring 2005–2015. Keep distinct source result rows, do not assign independent family weight until overlap adjudicated.')
print('Stahl:',len(rows),'food monitoring groups; overlap flagged.')

r=source('rebellato2023b');rows=[]
for lot,values in [('A',[(.14,.00),(1.34,.02),(.18,.00),(.19,.03),(4.30,.87)]),('B',[(.15,.01),(1.36,.05),(.18,.01),(.24,.03),(None,None)]),('C',[(.13,.00),(1.00,.06),(.16,.01),(.34,.02),(4.87,.26)])]:
    for metal,(mean,sd) in zip(['Cu','Fe','Mn','Zn','Se'],values):
        factor=.01 if metal=='Se' else 10
        rows.append(dict(id=f'rebellato2023b-s13-{lot}-{metal}',analyte=metal,form='cocoa and soy-protein-isolate plant-based yogurt',market='Campinas, São Paulo, Brazil retail; ingredient origins unspecified',year='collection date not reported',n=1,sample_unit='commercial lot',n_note='Three lots of sample 13; n=3 in the table is triplicate analytical digestion, not three additional product lots per row.',reported=dict(mean=mean,sd=sd,unit='µg/100 g' if metal=='Se' else 'mg/100 g'),value=None if mean is None else mean*factor,lower_bound=0 if mean is None else mean*factor,upper_bound=.004 if mean is None else mean*factor,unit='mg/kg',statistic='triplicate analytical mean ±SD for one commercial lot' if mean is not None else 'below quantification limit',basis='yogurt homogenate as sold, no dry-weight conversion',locator=f'Table 2 continuation, PDF page 4, sample 13 lot {lot}, {metal}',censoring='Se <0.4 µg/100 g (=.004 mg/kg), not zero.' if mean is None else 'Positive printed result; zero SD is reported rounded analytical dispersion, not proof of no variability.',limitations='Whole formulated yogurt, with soy isolate and tricalcium phosphate; its element content cannot be attributed solely to cocoa.'))
for metal,mean,sd in [('Al',None,None),('Ba',700,24),('Co',28.0,2.3),('Cr',37.0,3.2),('Mo',None,None),('Ni',454,34)]:
    bound=.2 if metal=='Al' else .004
    rows.append(dict(id=f'rebellato2023b-s13-bioaccess-input-{metal}',analyte=metal,form='cocoa/soy plant-based yogurt, selected in-vitro assay input',market='Campinas, Brazil retail',year='not reported',n=1,sample_unit='selected yogurt material for triplicate simulated digestion; exact lot relationship unreported',reported=dict(mean=mean,sd=sd,unit='µg/kg'),value=None if mean is None else mean/1000,lower_bound=0 if mean is None else mean/1000,upper_bound=bound if mean is None else mean/1000,unit='mg/kg',statistic='assay-input total content ±analytical SD',basis='original whole yogurt input, not the diluted soluble fraction',locator=f'Table 6, PDF page 7, sample 13 total content {metal}',censoring=f'Below source LOQ, retained as 0–{bound} mg/kg identification interval.' if mean is None else 'Printed quantified total input.',limitations='Some input totals differ from Table 2 per-lot concentrations; do not silently repair or treat these as an independent fourth commercial lot.'))
save(r,rows,extraction_complete=True,identity_proof='Complete nine-page Rebellato et al., Journal of Food Composition and Analysis 123 (2023) 105639; title/authors, DOI, Methods and all six tables and final PCA figure assessed.',complete_scope='All five trace-element concentrations for all three explicitly cocoa-containing sample-13 lots, and six reported total assay-input trace-element concentrations. Macronutrient Ca/Mg/K/Na/P values are retained as nutritional context, not contaminant results. Other yogurt formulations cannot be assigned to cocoa.',
    nutritional_context=dict(locator='Table 2, PDF page 4, sample 13 lots A/B/C',unit='mg/100 g',Ca=[221,228,181],K=[124,128,94.2],Mg=[23.2,22.6,16.9],Na=[158,157,116],P=[178,188,140]),
    bioaccessibility_context=dict(locator='Tables 4 and 6, PDF pages 6–7, sample 13',method='Modified INFOGEST 2.0 in-vitro digestion, three separate repetitions; no gastric lipase; soluble fraction is not an absorbed human dose.',Cu=dict(input_mg_100g=.15,input_sd=.01,soluble_mg_100g=.09,soluble_sd=.00,percent=61.2),Ba=dict(input_ug_kg=700,soluble=237,soluble_sd=20,percent=33.9),Co=dict(input_ug_kg=28,soluble=25,soluble_sd=1.2,percent=89.0),Cr=dict(input_ug_kg=37,soluble=6.22,soluble_sd=.2,percent=16.8),Ni=dict(input_ug_kg=454,soluble=136,soluble_sd=4,percent=29.9),limit='Digestion partition is exposure context, not a kitchen treatment or a demonstrated reduction in original food concentration. Nd soluble fractions do not make the original food analyte-free.'))
print('Rebellato bioaccessibility paper:',len(rows),'cocoa-yogurt concentration records; soluble outputs retained separately.')

p=D/'content-dispositions.json';j=json.loads(p.read_text())
for prefix,data in {
 'romero-crespo2023':dict(disposition='out_of_scope',locator='Primary converted article Materials/Methods crop sampling and Table 1; introduction cocoa citation on converted page 1',rationale='Actual edible samples are celery, chives, corn, herbs, lettuce, turnips, green beans, cassava and carrots from mining-area orchards. Cocoa is mentioned as a regional export crop and as background citations to other studies, not as an assayed edible matrix. No vegetable metal result is routed to cocoa.',identity_proof='Complete Romero-Crespo et al. 2023 primary article, DOI 10.1007/s10653-023-01514-x, exact title/authors and full crop results.'),
 'oseisafo2024':dict(disposition='out_of_scope',locator='Primary Methods §2.6–2.7 and Table 4; source spice sample list Table 1',rationale='Cocoa powder FAPAS 07340 is the certified reference material used to validate spice assays, not a surveyed cocoa product. CRM certified/measured recoveries are analytical quality control, not market cocoa occurrence. Original sampled spices remain outside Cocoa.',identity_proof='Osei-Safo et al., Scientific World Journal 2024 article 3168279, complete 10-page primary article, DOI 10.1155/2024/3168279.'),
 'sadeghi2021':dict(disposition='context_only',locator='PDF page 2 Methods §2.1, page 3 Results grouped simple/flavoured measurements and Figure 1',rationale='74 tahini samples from 37 brands include five flavours: coffee, chocolate, date, vanilla and cocoa. Published results combine all flavours; cocoa/chocolate identities are not linked to individual measured results. Flavoured-tahini aggregate cannot be presented as a cocoa-specific concentration or cocoa-only treatment contrast.',identity_proof='Complete six-page Sadeghi et al., Journal of Human, Health and Halal Metrics 2021 2(1):40–45; DOI 10.30502/jhhhm.2021.288521.1034.')
}.items():
    rr=source(prefix);data.update(artifact=rr['resolved_path'],sha256=rr['artifact_sha256']);j['decisions'][rr['source_id']]=data
p.write_text(json.dumps(j,ensure_ascii=False,indent=2)+'\n')
